package mobileapi

// Mirror pins for the mobile facade (final pass 3).
//
// core/mobileapi is the Go surface the Android (Kotlin/gomobile) and
// iOS (Swift/C-shim) clients are written against by hand: the Swift
// side re-declares the API as a protocol plus a generated-shim struct
// whose bodies call the gomobile symbols by name, the Kotlin side
// calls the gomobile class directly, and both sides re-declare the
// JSON document shapes (Server / Plan / EngineInfo) as their own
// Codable/data types. None of that is regenerated by any build step
// in this repository, so a renamed Go export or a renamed JSON tag
// compiles fine on the Go side and breaks only on a device. These
// tests read the consumer sources and pin the mirrors:
//
//   - the exported function set of this package == the Swift
//     MobileAPI protocol == the gomobile symbols the Swift shim
//     calls == the Kotlin call sites;
//   - the JSON tags of Server/Plan/Group/Rule and of the EngineInfo
//     document == the Swift CodingKeys of the mirror types;
//   - DefaultLocalPort == the default spelled in the Kotlin store,
//     the Swift store and the Swift exchange type;
//   - the TUN inbound constants the two mobile clients inject
//     (tag, addresses, stack) are the same in Kotlin and Swift —
//     each file calls itself the mirror of the other, and until now
//     nothing checked that claim.

import (
	"encoding/json"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"reflect"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"testing"
)

func mobileRoot(t *testing.T) string {
	t.Helper()
	root, err := filepath.Abs(filepath.Join("..", ".."))
	if err != nil {
		t.Fatal(err)
	}
	if _, err := os.Stat(filepath.Join(root, "core", "mobileapi", "mobileapi.go")); err != nil {
		t.Fatalf("repository root not found from the mobileapi package: %v", err)
	}
	return root
}

func mobileRead(t *testing.T, root, rel string) string {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(rel)))
	if err != nil {
		t.Fatalf("read %s: %v", rel, err)
	}
	return string(raw)
}

func lowerFirst(s string) string {
	if s == "" {
		return s
	}
	return strings.ToLower(s[:1]) + s[1:]
}

func sortedKeys[V any](m map[string]V) []string {
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

// exportedFacadeFuncs returns the exported package-level functions of
// mobileapi.go — the exact surface gomobile binds.
func exportedFacadeFuncs(t *testing.T, root string) []string {
	t.Helper()
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, filepath.Join(root, "core", "mobileapi", "mobileapi.go"), nil, 0)
	if err != nil {
		t.Fatal(err)
	}
	var out []string
	for _, decl := range file.Decls {
		fn, ok := decl.(*ast.FuncDecl)
		if ok && fn.Recv == nil && fn.Name.IsExported() {
			out = append(out, fn.Name.Name)
		}
	}
	sort.Strings(out)
	return out
}

func TestMobileAPIMirrorFunctionSurface(t *testing.T) {
	root := mobileRoot(t)
	goFuncs := exportedFacadeFuncs(t, root)
	if len(goFuncs) == 0 {
		t.Fatal("no exported facade functions parsed")
	}

	// Swift protocol: the methods of `public protocol MobileAPI`.
	swiftClient := mobileRead(t, root, "ios/SoraLegacyCore/Sources/SoraLegacyCore/MobileAPIClient.swift")
	protoStart := strings.Index(swiftClient, "public protocol MobileAPI {")
	if protoStart < 0 {
		t.Fatal("Swift MobileAPI protocol not found")
	}
	protoBody := swiftClient[protoStart:]
	if end := strings.Index(protoBody, "\n}"); end >= 0 {
		protoBody = protoBody[:end]
	}
	var swiftFuncs []string
	for _, m := range regexp.MustCompile(`func (\w+)\(`).FindAllStringSubmatch(protoBody, -1) {
		swiftFuncs = append(swiftFuncs, m[1])
	}
	sort.Strings(swiftFuncs)
	wantSwift := make([]string, 0, len(goFuncs))
	for _, f := range goFuncs {
		wantSwift = append(wantSwift, lowerFirst(f))
	}
	sort.Strings(wantSwift)
	if strings.Join(swiftFuncs, ",") != strings.Join(wantSwift, ",") {
		t.Errorf("Swift MobileAPI protocol = %v, the Go facade exports %v", swiftFuncs, goFuncs)
	}

	// Swift shim: the gomobile symbols GeneratedMobileAPI calls are
	// spelled Mobileapi<Export>.
	shim := mobileRead(t, root, "ios/SoraLegacyCore/Sources/SoraLegacyCore/MobileAPIGenerated.swift")
	gotShim := map[string]bool{}
	for _, m := range regexp.MustCompile(`\bMobileapi(\w+)\(`).FindAllStringSubmatch(shim, -1) {
		gotShim[m[1]] = true
	}
	for _, f := range goFuncs {
		if !gotShim[f] {
			t.Errorf("Go export %s is never called by the Swift shim (Mobileapi%s)", f, f)
		}
	}
	for name := range gotShim {
		found := false
		for _, f := range goFuncs {
			if f == name {
				found = true
			}
		}
		if !found {
			t.Errorf("the Swift shim calls Mobileapi%s, which the Go facade does not export", name)
		}
	}

	// Kotlin: gomobile call sites across the Android client.
	ktDir := filepath.Join(root, "android", "app", "src", "main", "java", "one", "levvs", "sora", "legacy")
	entries, err := os.ReadDir(ktDir)
	if err != nil {
		t.Fatal(err)
	}
	gotKotlin := map[string]bool{}
	for _, e := range entries {
		if !strings.HasSuffix(e.Name(), ".kt") {
			continue
		}
		src := mobileRead(t, root, "android/app/src/main/java/one/levvs/sora/legacy/"+e.Name())
		for _, m := range regexp.MustCompile(`Mobileapi\.(\w+)\(`).FindAllStringSubmatch(src, -1) {
			gotKotlin[m[1]] = true
		}
	}
	for _, f := range goFuncs {
		if !gotKotlin[lowerFirst(f)] {
			t.Errorf("Go export %s has no Kotlin call site (Mobileapi.%s)", f, lowerFirst(f))
		}
	}
	for name := range gotKotlin {
		found := false
		for _, f := range goFuncs {
			if lowerFirst(f) == name {
				found = true
			}
		}
		if !found {
			t.Errorf("Kotlin calls Mobileapi.%s, which the Go facade does not export", name)
		}
	}
}

// jsonTags returns the JSON field names of a struct type, in
// declaration order, skipping "-" and untagged-unexported fields.
func jsonTags(v any) []string {
	typ := reflect.TypeOf(v)
	var out []string
	for i := 0; i < typ.NumField(); i++ {
		f := typ.Field(i)
		tag := f.Tag.Get("json")
		if tag == "-" {
			continue
		}
		name, _, _ := strings.Cut(tag, ",")
		if name == "" {
			name = f.Name
		}
		out = append(out, name)
	}
	sort.Strings(out)
	return out
}

// balancedBody returns the text inside the braces that start at
// index open (which must point at a '{').
func balancedBody(src string, open int) string {
	depth := 0
	for j := open; j < len(src); j++ {
		switch src[j] {
		case '{':
			depth++
		case '}':
			depth--
			if depth == 0 {
				return src[open+1 : j]
			}
		}
	}
	return src[open+1:]
}

// swiftStructBody extracts one Swift struct's own body from
// Models.swift, with nested type declarations cut out, so a nested
// struct's CodingKeys cannot pose as the outer type's.
func swiftStructBody(t *testing.T, models, structName string) string {
	t.Helper()
	re := regexp.MustCompile(`(?:public\s+)?struct ` + structName + `\b`)
	loc := re.FindStringIndex(models)
	if loc == nil {
		t.Fatalf("Swift struct %s not found", structName)
	}
	open := strings.Index(models[loc[0]:], "{")
	if open < 0 {
		t.Fatalf("Swift struct %s has no body", structName)
	}
	body := balancedBody(models, loc[0]+open)
	// Cut nested struct declarations with balanced bodies (their
	// CodingKeys enums go with them); the struct's own CodingKeys
	// enum stays.
	for {
		nested := regexp.MustCompile(`(?:public\s+)?struct \w+[^{]*\{`).FindStringIndex(body)
		if nested == nil {
			break
		}
		inner := balancedBody(body, nested[1]-1)
		body = body[:nested[0]] + body[nested[1]+len(inner)+1:]
	}
	return body
}

// swiftJSONKeys extracts the JSON keys of one Swift struct in a
// Models.swift source: the raw values of its CodingKeys when it
// declares them, otherwise its stored property names.
func swiftJSONKeys(t *testing.T, models, structName string) []string {
	t.Helper()
	body := swiftStructBody(t, models, structName)
	var keys []string
	if ck := regexp.MustCompile(`(?s)enum CodingKeys[^{]*\{(.*?)\}`).FindStringSubmatch(body); ck != nil {
		// Case lines may declare several cases comma-separated.
		for _, cm := range regexp.MustCompile(`case\s+([^\n]+)`).FindAllStringSubmatch(ck[1], -1) {
			for _, part := range strings.Split(cm[1], ",") {
				part = strings.TrimSpace(part)
				if part == "" {
					continue
				}
				if kv := strings.SplitN(part, "=", 2); len(kv) == 2 {
					raw := strings.Trim(strings.TrimSpace(kv[1]), `"`)
					// Raw values may be backtick-escaped identifiers.
					keys = append(keys, strings.Trim(raw, "`"))
				} else {
					keys = append(keys, strings.Trim(part, "`"))
				}
			}
		}
	} else {
		for _, pm := range regexp.MustCompile(`public var (\w+):`).FindAllStringSubmatch(body, -1) {
			keys = append(keys, pm[1])
		}
	}
	if len(keys) == 0 {
		t.Fatalf("Swift struct %s: no JSON keys extracted", structName)
	}
	sort.Strings(keys)
	return keys
}

func TestMobileAPIMirrorJSONShapes(t *testing.T) {
	root := mobileRoot(t)
	models := mobileRead(t, root, "ios/SoraLegacyCore/Sources/SoraLegacyCore/Models.swift")

	check := func(name string, goShape any, swiftStruct string) {
		t.Helper()
		got := swiftJSONKeys(t, models, swiftStruct)
		want := jsonTags(goShape)
		if strings.Join(got, ",") != strings.Join(want, ",") {
			t.Errorf("%s: Swift keys %v, Go json tags %v", name, got, want)
		}
	}
	check("Server", Server{}, "Server")
	check("Plan", Plan{}, "PlanDocument")
	check("Plan.Group", Group{}, "Group")
	check("Plan.Rule", Rule{}, "Rule")

	// EngineInfo is an anonymous document in Go; its shape is pinned
	// here from the marshalled output against the Swift mirror type.
	var infoDoc struct {
		Engines []struct {
			Kind       string   `json:"kind"`
			MinVersion string   `json:"min_version"`
			Protocols  []string `json:"protocols"`
			Features   []string `json:"features"`
		} `json:"engines"`
		DefaultPreference []string `json:"default_preference"`
	}
	if err := json.Unmarshal([]byte(EngineInfo()), &infoDoc); err != nil {
		t.Fatalf("EngineInfo document does not decode into its own mirror shape: %v", err)
	}
	if len(infoDoc.Engines) == 0 || len(infoDoc.DefaultPreference) == 0 {
		t.Fatal("EngineInfo document is empty")
	}
	if got := swiftJSONKeys(t, models, "EngineInfo"); strings.Join(got, ",") != "default_preference,engines" {
		t.Errorf("Swift EngineInfo keys = %v, the Go document carries engines/default_preference", got)
	}
	if got := swiftJSONKeys(t, models, "Engine"); strings.Join(got, ",") != "features,kind,min_version,protocols" {
		t.Errorf("Swift EngineInfo.Engine keys = %v, the Go document carries kind/min_version/protocols/features", got)
	}

	// The macOS client decodes the same EngineInfo document (via the
	// sora-ctl helper) into its own EngineCatalog type: same mirror,
	// second spelling.
	macModels := mobileRead(t, root, "macos/App/Core/Models.swift")
	if got := swiftJSONKeys(t, macModels, "EngineCatalog"); strings.Join(got, ",") != "default_preference,engines" {
		t.Errorf("macOS EngineCatalog keys = %v, the Go document carries engines/default_preference", got)
	}
	if got := swiftJSONKeys(t, macModels, "Engine"); strings.Join(got, ",") != "features,kind,min_version,protocols" {
		t.Errorf("macOS EngineCatalog.Engine keys = %v, the Go document carries kind/min_version/protocols/features", got)
	}

	// The Kotlin side builds the plan document by hand; the keys it
	// writes must be real Plan fields.
	kt := mobileRead(t, root, "android/app/src/main/java/one/levvs/sora/legacy/SoraVpnService.kt")
	planTags := map[string]bool{}
	for _, tag := range jsonTags(Plan{}) {
		planTags[tag] = true
	}
	wrote := map[string]bool{}
	for _, m := range regexp.MustCompile(`\.put\("(\w+)"`).FindAllStringSubmatch(kt, -1) {
		wrote[m[1]] = true
	}
	for _, key := range []string{"local_port", "servers"} {
		if !wrote[key] {
			t.Fatalf("SoraVpnService no longer writes plan key %q", key)
		}
		if !planTags[key] {
			t.Errorf("SoraVpnService writes plan key %q, which is not a field of mobileapi.Plan", key)
		}
	}
}

func TestMobileAPIMirrorLocalPortDefault(t *testing.T) {
	root := mobileRoot(t)
	want := strconv.Itoa(DefaultLocalPort)
	sites := []struct{ rel, pattern string }{
		{"android/app/src/main/java/one/levvs/sora/legacy/ServerStore.kt", `KEY_LOCAL_PORT, (\d+)`},
		{"ios/SoraLegacyCore/Sources/SoraLegacyCore/ServerStore.swift", `value == 0 \? (\d+) : value`},
		{"ios/SoraLegacyCore/Sources/SoraLegacyCore/Models.swift", `localPort: Int = (\d+)`},
	}
	for _, site := range sites {
		m := regexp.MustCompile(site.pattern).FindStringSubmatch(mobileRead(t, root, site.rel))
		if m == nil {
			t.Fatalf("%s: local-port default not found", site.rel)
		}
		if m[1] != want {
			t.Errorf("%s: local-port default = %s, mobileapi.DefaultLocalPort = %s", site.rel, m[1], want)
		}
	}
}

func TestMobileAPIMirrorTunConfig(t *testing.T) {
	root := mobileRoot(t)
	kt := mobileRead(t, root, "android/app/src/main/java/one/levvs/sora/legacy/TunConfig.kt")
	sw := mobileRead(t, root, "ios/SoraLegacyCore/Sources/SoraLegacyCore/TunConfig.swift")

	extract := func(src, pattern string) string {
		m := regexp.MustCompile(pattern).FindStringSubmatch(src)
		if m == nil {
			return ""
		}
		return m[1]
	}
	pairs := []struct{ name, ktPattern, swPattern string }{
		{"tag", `TUN_TAG = "([^"]+)"`, `tunTag = "([^"]+)"`},
		{"inet4", `INET4_ADDRESS = "([^"]+)"`, `inet4Address = "([^"]+)"`},
		{"inet6", `INET6_ADDRESS = "([^"]+)"`, `inet6Address = "([^"]+)"`},
	}
	for _, p := range pairs {
		kv, sv := extract(kt, p.ktPattern), extract(sw, p.swPattern)
		if kv == "" || sv == "" {
			t.Fatalf("TunConfig %s: Kotlin %q / Swift %q — constant not found on one side", p.name, kv, sv)
		}
		if kv != sv {
			t.Errorf("TunConfig %s: Kotlin spells %q, Swift spells %q", p.name, kv, sv)
		}
	}
	// Both inject the same stack spelling.
	if !strings.Contains(kt, `"stack", "mixed"`) || !strings.Contains(sw, `"stack": "mixed"`) {
		t.Error("TunConfig stack: Kotlin and Swift must both inject \"mixed\"")
	}
	// The MTU default the Swift store falls back to is the constant
	// the Kotlin store spells as its own default.
	swMTU := extract(sw, `defaultMTU = (\d+)`)
	ktStore := mobileRead(t, root, "android/app/src/main/java/one/levvs/sora/legacy/ServerStore.kt")
	ktStoreMTU := extract(ktStore, `KEY_TUN_MTU, (\d+)`)
	if swMTU == "" || ktStoreMTU == "" || swMTU != ktStoreMTU {
		t.Errorf("TUN MTU default: Swift TunConfig %q, Kotlin store %q", swMTU, ktStoreMTU)
	}
}
